    import random
    import time

    LANGUAGE_WRAPPER = 'Consider the equation sum_{j=1}^{k} c_j * (a_j - x)^{n} = 0, where n={n}, k={k}, c={c_list}, and a={a_list}. Assume n is odd and the cancellation conditions sum c_j = 0 and sum c_j * a_j = 0 hold, while sum c_j * a_j^2 != 0. Find the sum of all roots (real and non-real), counted with multiplicity.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose n odd with n ≡ 2 (mod 3) so (n-2)/3 is integer, and reasonably large to avoid triviality
options = [17, 23, 29, 35, 41, 47, 53, 59]
n = rng.choice(options)
k = 3
# Construct parameters via a structured scheme ensuring sum c_j = 0 and sum c_j a_j = 0
# Let a = [0, u, v], c = [u - v, v, -u]; then sum c = 0 and sum c*a = v*u + (-u)*v = 0
# Also s2 = sum c*a^2 = v*u^2 - u*v^2 = uv(u - v) != 0 for u != v
# s3/s2 = (u+v) is integer, so the final answer is integer since (n-2)/3 is integer
attempts = 0
while True:
    attempts += 1
    if attempts > 1000:
        # Fallback in the unlikely event of persistent failure
        n = 23
    u = rng.randint(2, 12)
    v = rng.randint(2, 12)
    if u == v:
        continue
    a_list = [0, u, v]
    c_list = [u - v, v, -u]
    # Validate constructed constraints
    sum_c = sum(c_list)
    sum_ca = sum(c_list[i] * a_list[i] for i in range(k))
    s2 = sum(c_list[i] * (a_list[i] ** 2) for i in range(k))
    s3 = sum(c_list[i] * (a_list[i] ** 3) for i in range(k))
    if sum_c != 0:
        continue
    if sum_ca != 0:
        continue
    if s2 == 0:
        continue
    # Ensure integer answer
    if s3 % s2 != 0:
        continue
    # All constraints satisfied
    return {'n': n, 'k': k, 'c_list': c_list, 'a_list': a_list}

    def verifier(assign):
# Validate presence and basic types
required = ('n', 'k', 'c_list', 'a_list')
if not all(key in assign for key in required):
    # Missing data
    return (False, None)
n = assign['n']
k = assign['k']
c_list = assign['c_list']
a_list = assign['a_list']
if not (isinstance(n, int) and isinstance(k, int) and isinstance(c_list, list) and isinstance(a_list, list)):
    return (False, None)
if len(c_list) != k or len(a_list) != k:
    return (False, None)
if any(not isinstance(x, int) for x in c_list+a_list):
    return (False, None)
# Enforce difficulty and well-posedness
if n < 11 or n % 2 != 1 or n % 3 != 2:
    # n must be odd, reasonably large, and congruent to 2 mod 3 to avoid trivial integrality issues
    return (False, None)
sum_c = sum(c_list)
sum_ca = sum(c_list[i] * a_list[i] for i in range(k))
s2 = sum(c_list[i] * (a_list[i] ** 2) for i in range(k))
s3 = sum(c_list[i] * (a_list[i] ** 3) for i in range(k))
if sum_c != 0:
    # Leading x^n term must cancel
    return (False, None)
if sum_ca != 0:
    # Next x^{n-1} term must cancel to raise difficulty
    return (False, None)
if s2 == 0:
    # Must have degree exactly n-2
    return (False, None)
# Ensure integer output to match contest-style answers
if s3 % s2 != 0:
    return (False, None)
# Using binomial expansion: for odd n, coefficient of x^{n-2} is -C(n,2)*s2, of x^{n-3} is +C(n,3)*s3
# Sum of roots (with multiplicity) of a degree m polynomial is -coef(x^{m-1})/leading_coef
# Here m = n-2; sum = -(C(n,3)*s3)/(-C(n,2)*s2) = (C(n,3)/C(n,2)) * (s3/s2) = ((n-2)/3) * (s3/s2)
answer = ((n - 2) // 3) * (s3 // s2)
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

